<div class="page-heading"><div><p class="eyebrow">Security</p><h1>Audit log</h1><p>Review sign-ins and important data changes.</p></div></div><form class="filter-bar" method="get" aria-label="Filter audit log"><label class="filter-field">Search<input name="q" value="<?=e($q)?>" placeholder="User, entity, or record ID"></label><label class="filter-field">Action<input name="action" value="<?=e($action)?>" placeholder="Action contains"></label><button class="button">Filter entries</button></form><section class="card table-card"><table><thead><tr><th scope="col">Date</th><th scope="col">User</th><th scope="col">Action</th><th scope="col">Record</th><th scope="col">IP address</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td><?=e($log['created_at'])?></td><td><?=e($log['display_name']?:'System/unknown')?></td><td><strong><?=e($log['action'])?></strong></td><td><?=e(trim(($log['entity_type']??'').' #'.($log['entity_id']??''),' #'))?></td><td><?=e($log['ip_address'])?></td></tr><?php endforeach;?><?php if(!$logs):?><tr><td colspan="5" class="empty">No audit entries match these filters.</td></tr><?php endif;?></tbody></table></section>
